"""Writes crates/archisim-ids/src/schema_data.rs: for each IFC schema
(IFC2X3, IFC4, IFC4X3), every entity with its supertype and its own explicit
attributes, in file order. Only names: the facts of the published schemas.

    python3 scripts/make_ifc_schema.py   # requires: pip install ifcopenshell
"""
import os
import ifcopenshell.ifcopenshell_wrapper as w

OUT = os.path.join(os.path.dirname(__file__), "..", "crates", "archisim-ids", "src", "schema_data.rs")

lines = [
    "// Generated by scripts/make_ifc_schema.py from the IFC schemas. Do not edit.",
    "//! Entity names, supertypes and own explicit attributes of IFC2X3, IFC4",
    "//! and IFC4X3, in the order they are written in a STEP file.",
    "",
    "/// (entity, supertype or \"\", own attributes, abstract)",
    "pub type Row = (&'static str, &'static str, &'static [&'static str], bool);",
    "",
]
for name, rust in (("IFC2X3", "IFC2X3"), ("IFC4", "IFC4"), ("IFC4X3_ADD2", "IFC4X3")):
    s = w.schema_by_name(name)
    rows = []
    for d in s.declarations():
        if not hasattr(d, "all_attributes") or not hasattr(d, "supertype"):
            continue
        sup = d.supertype()
        own = [a.name() for a in d.attributes()]
        rows.append((d.name().upper(), sup.name().upper() if sup else "", own, d.is_abstract()))
    rows.sort()
    lines.append(f"pub static {rust}: &[Row] = &[")
    for n, sup, own, ab in rows:
        attrs = ", ".join(f'"{a}"' for a in own)
        lines.append(f'    ("{n}", "{sup}", &[{attrs}], {str(ab).lower()}),')
    lines.append("];")
    lines.append("")
open(OUT, "w").write("\n".join(lines))
print(OUT, sum(1 for l in lines if l.startswith('    (')))
